<?php
declare(strict_types=1);
namespace Dreamsmith\Campaign\Prospect;
use Dreamsmith\Campaign\Application\Audit\ActorContext;use Dreamsmith\Campaign\Application\Audit\AuditWriter;use Dreamsmith\Campaign\Persistence\Database;use Dreamsmith\Campaign\Records\StaleRecordVersion;use Dreamsmith\Campaign\Support\Clock;use PDO;use PDOException;
final class ProspectService{
 public function __construct(private readonly Database $db,private readonly AuditWriter $audit,private readonly Clock $clock,private readonly ProspectRules $rules){}
 public function create(ProspectInput $i,int $owner,string $cid):int{return $this->db->transaction(function(PDO $p)use($i,$owner,$cid){$campaign=$p->query('SELECT active_campaign_id FROM application_settings WHERE id=1 FOR UPDATE')->fetchColumn();if(!$campaign)throw new \DomainException('Configure and activate a campaign first.');$this->identity($p,$i);try{$s=$p->prepare('INSERT INTO prospects(campaign_id,company_id,primary_contact_id,segment,source,why_them,business_problem,qualification_notes,problem_understood,timing_understood,buyer_understood,budget_plausible) VALUES(:campaign,:company,:contact,:segment,:source,:why,:problem_text,:notes,:problem,:timing,:buyer,:budget)');$s->execute($this->params($i)+['campaign'=>$campaign]);}catch(PDOException $e){if($e->getCode()==='23000')throw new \DomainException('This active prospect identity already exists in the campaign.');throw $e;}$id=(int)$p->lastInsertId();$p->prepare("INSERT INTO prospect_status_events(prospect_id,from_status,to_status,occurred_at,actor_user_id) VALUES(:id,NULL,'researching',:at,:owner)")->execute(['id'=>$id,'at'=>$this->at(),'owner'=>$owner]);$this->audit($p,$owner,$cid,'prospect.created',$id);return $id;});}
 public function update(int $id,ProspectInput $i,int $version,int $owner,string $cid):void{$this->db->transaction(function(PDO $p)use($id,$i,$version,$owner,$cid){$r=new ProspectRepository($p);$cur=$r->find($id,true);$this->current($cur,$version);$this->identity($p,$i);try{$p->prepare('UPDATE prospects SET company_id=:company,primary_contact_id=:contact,segment=:segment,source=:source,why_them=:why,business_problem=:problem_text,qualification_notes=:notes,problem_understood=:problem,timing_understood=:timing,buyer_understood=:buyer,budget_plausible=:budget,version=version+1 WHERE id=:id')->execute($this->params($i)+['id'=>$id]);}catch(PDOException $e){if($e->getCode()==='23000')throw new \DomainException('This active prospect identity already exists in the campaign.');throw $e;}$this->audit($p,$owner,$cid,'prospect.updated',$id);});}
 public function transition(int $id,string $to,string $reason,int $version,int $owner,string $cid):void{$this->db->transaction(function(PDO $p)use($id,$to,$reason,$version,$owner,$cid){$r=new ProspectRepository($p);$cur=$r->find($id,true);$this->current($cur,$version);if($cur['archived_at']!==null)throw new \DomainException('Restore the prospect before changing status.');$unmet=$this->rules->unmet($cur['segment'],$to,$cur['why_them'],count($r->signals($id,true)),$cur['business_problem'],(bool)$cur['problem_understood'],(bool)$cur['timing_understood'],(bool)$cur['buyer_understood'],(bool)$cur['budget_plausible']);$this->rules->assertTransition($cur['status'],$to,$unmet);$p->prepare('UPDATE prospects SET status=:status,version=version+1 WHERE id=:id')->execute(['status'=>$to,'id'=>$id]);$p->prepare('INSERT INTO prospect_status_events(prospect_id,from_status,to_status,occurred_at,reason,actor_user_id) VALUES(:id,:from,:to,:at,:reason,:owner)')->execute(['id'=>$id,'from'=>$cur['status'],'to'=>$to,'at'=>$this->at(),'reason'=>trim($reason)?:null,'owner'=>$owner]);$this->audit($p,$owner,$cid,'prospect.transitioned',$id);});}
 public function addSignal(int $id,int $signalId,string $evidence,?string $observed,int $version,int $owner,string $cid):void{$evidence=trim($evidence);if($evidence==='')throw new \InvalidArgumentException('Signal evidence is required.');$observed=$this->date($observed);$this->db->transaction(function(PDO $p)use($id,$signalId,$evidence,$observed,$version,$owner,$cid){$r=new ProspectRepository($p);$cur=$r->find($id,true);$this->current($cur,$version);$check=$p->prepare('SELECT id FROM signals WHERE id=:id');$check->execute(['id'=>$signalId]);if(!$check->fetchColumn())throw new \InvalidArgumentException('Select a valid signal.');try{$p->prepare('INSERT INTO prospect_signals(prospect_id,signal_id,evidence_note,observed_on) VALUES(:prospect,:signal,:evidence,:observed)')->execute(['prospect'=>$id,'signal'=>$signalId,'evidence'=>$evidence,'observed'=>$observed]);}catch(PDOException $e){if($e->getCode()==='23000')throw new \DomainException('That signal already has evidence for this prospect.');throw $e;}$p->prepare('UPDATE prospects SET version=version+1 WHERE id=:id')->execute(['id'=>$id]);$this->audit($p,$owner,$cid,'prospect.signal_added',$id);});}
 public function removeSignal(int $id,int $evidenceId,int $prospectVersion,int $evidenceVersion,int $owner,string $cid):void{$this->db->transaction(function(PDO $p)use($id,$evidenceId,$prospectVersion,$evidenceVersion,$owner,$cid){$cur=(new ProspectRepository($p))->find($id,true);$this->current($cur,$prospectVersion);$s=$p->prepare('SELECT * FROM prospect_signals WHERE id=:evidence AND prospect_id=:prospect FOR UPDATE');$s->execute(['evidence'=>$evidenceId,'prospect'=>$id]);$e=$s->fetch();if(!$e)throw new \OutOfBoundsException('Signal evidence not found.');if((int)$e['version']!==$evidenceVersion)throw new StaleRecordVersion('Signal evidence changed.');$p->prepare('DELETE FROM prospect_signals WHERE id=:id')->execute(['id'=>$evidenceId]);$p->prepare('UPDATE prospects SET version=version+1 WHERE id=:id')->execute(['id'=>$id]);$this->audit($p,$owner,$cid,'prospect.signal_removed',$id);});}
 public function updateSignal(int $id,int $evidenceId,string $evidence,?string $observed,int $prospectVersion,int $evidenceVersion,int $owner,string $cid):void{$evidence=trim($evidence);if($evidence==='')throw new \InvalidArgumentException('Signal evidence is required.');$observed=$this->date($observed);$this->db->transaction(function(PDO $p)use($id,$evidenceId,$evidence,$observed,$prospectVersion,$evidenceVersion,$owner,$cid){$cur=(new ProspectRepository($p))->find($id,true);$this->current($cur,$prospectVersion);$s=$p->prepare('SELECT version FROM prospect_signals WHERE id=:evidence AND prospect_id=:prospect FOR UPDATE');$s->execute(['evidence'=>$evidenceId,'prospect'=>$id]);$version=$s->fetchColumn();if($version===false)throw new \OutOfBoundsException('Signal evidence not found.');if((int)$version!==$evidenceVersion)throw new StaleRecordVersion('Signal evidence changed.');$p->prepare('UPDATE prospect_signals SET evidence_note=:evidence,observed_on=:observed,version=version+1 WHERE id=:id')->execute(['evidence'=>$evidence,'observed'=>$observed,'id'=>$evidenceId]);$p->prepare('UPDATE prospects SET version=version+1 WHERE id=:id')->execute(['id'=>$id]);$this->audit($p,$owner,$cid,'prospect.signal_updated',$id);});}
 public function voidLatestEvent(int $id,int $eventId,int $prospectVersion,int $eventVersion,string $reason,int $owner,string $cid):void{$reason=trim($reason);if($reason==='')throw new \InvalidArgumentException('A void reason is required.');$this->db->transaction(function(PDO $p)use($id,$eventId,$prospectVersion,$eventVersion,$reason,$owner,$cid){$cur=(new ProspectRepository($p))->find($id,true);$this->current($cur,$prospectVersion);$s=$p->prepare('SELECT * FROM prospect_status_events WHERE prospect_id=:id AND voided_at IS NULL ORDER BY occurred_at DESC,id DESC LIMIT 1 FOR UPDATE');$s->execute(['id'=>$id]);$latest=$s->fetch();if(!$latest||(int)$latest['id']!==$eventId)throw new \DomainException('Only the latest valid status event can be voided.');if((int)$latest['version']!==$eventVersion)throw new StaleRecordVersion('Status event changed.');if($latest['from_status']===null&&$cur['archived_at']===null)throw new \DomainException('The initial event cannot be voided while the prospect is active.');$p->prepare('UPDATE prospect_status_events SET voided_at=:at,voided_reason=:reason,voided_by_user_id=:owner,version=version+1 WHERE id=:id')->execute(['at'=>$this->at(),'reason'=>$reason,'owner'=>$owner,'id'=>$eventId]);$s=$p->prepare('SELECT to_status FROM prospect_status_events WHERE prospect_id=:id AND voided_at IS NULL ORDER BY occurred_at DESC,id DESC LIMIT 1');$s->execute(['id'=>$id]);$status=$s->fetchColumn();if(!$status)throw new \DomainException('A prospect must retain a valid status event.');$p->prepare('UPDATE prospects SET status=:status,version=version+1 WHERE id=:id')->execute(['status'=>$status,'id'=>$id]);$this->audit($p,$owner,$cid,'prospect.status_event_voided',$id);});}
 public function archive(int $id,int $version,bool $restore,int $owner,string $cid):void{$this->db->transaction(function(PDO $p)use($id,$version,$restore,$owner,$cid){$cur=(new ProspectRepository($p))->find($id,true);$this->current($cur,$version);if($restore){$this->identity($p,new ProspectInput($cur['company_id']? (int)$cur['company_id']:null,$cur['primary_contact_id']?(int)$cur['primary_contact_id']:null,$cur['segment'],$cur['source'],$cur['why_them'],$cur['business_problem'],$cur['qualification_notes'],(bool)$cur['problem_understood'],(bool)$cur['timing_understood'],(bool)$cur['buyer_understood'],(bool)$cur['budget_plausible']));}try{$p->prepare('UPDATE prospects SET archived_at='.($restore?'NULL':'UTC_TIMESTAMP(6)').',version=version+1 WHERE id=:id')->execute(['id'=>$id]);}catch(PDOException $e){if($e->getCode()==='23000')throw new \DomainException('An active prospect with this identity already exists.');throw $e;}$this->audit($p,$owner,$cid,$restore?'prospect.restored':'prospect.archived',$id);});}
 /** @param array<string,mixed>|null $c */ private function current(?array $c,int $v):void{if(!$c)throw new \OutOfBoundsException('Prospect not found.');if((int)$c['version']!==$v)throw new StaleRecordVersion('Prospect changed while you were editing.');}
 private function identity(PDO $p,ProspectInput $i):void{if($i->companyId){$s=$p->prepare('SELECT archived_at FROM companies WHERE id=:id FOR UPDATE');$s->execute(['id'=>$i->companyId]);$c=$s->fetch();if(!$c||$c['archived_at']!==null)throw new \DomainException('Select an active company.');}if($i->contactId){$s=$p->prepare('SELECT company_id,archived_at FROM contacts WHERE id=:id FOR UPDATE');$s->execute(['id'=>$i->contactId]);$c=$s->fetch();if(!$c||$c['archived_at']!==null)throw new \DomainException('Select an active contact.');if($i->companyId&&(int)$c['company_id']!==$i->companyId)throw new \DomainException('The primary contact must belong to the selected company.');}}
 private function params(ProspectInput $i):array{return['company'=>$i->companyId,'contact'=>$i->contactId,'segment'=>$i->segment,'source'=>$i->source,'why'=>$i->whyThem,'problem_text'=>$i->businessProblem,'notes'=>$i->qualificationNotes,'problem'=>$i->problem?1:0,'timing'=>$i->timing?1:0,'buyer'=>$i->buyer?1:0,'budget'=>$i->budget?1:0];}
 private function at():string{return $this->clock->now()->format('Y-m-d H:i:s.u');}
 private function date(?string $value):?string{if($value===null||$value==='')return null;$date=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);$errors=\DateTimeImmutable::getLastErrors();if($date===false||($errors!==false&&($errors['warning_count']||$errors['error_count'])))throw new \InvalidArgumentException('Observed date is invalid.');return $date->format('Y-m-d');}
 private function audit(PDO $p,int $owner,string $cid,string $op,int $id):void{$this->audit->write($p,new ActorContext('owner',ownerUserId:$owner,correlationId:$cid),$op,'prospect',$id,[],$this->clock->now());}
}
